import React, { useState, useEffect } from 'react';
import './Map.css'; // ייבוא הסגנונות של המפה

const Map = () => {
    const [map, setMap] = useState(null);

    useEffect(() => {
        // הפונקציה אתחול המפה
        function initMap() {
            // מיקום התחלתי (לדוגמה תל אביב)
            const telAviv = { lat: 32.0853, lng: 34.7818 };

            // יצירת אובייקט מפה
            const newMap = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: telAviv
            });

            // הוספת סימון למפה
            new window.google.maps.Marker({
                position: telAviv,
                map: newMap
            });

            setMap(newMap);
        }

        // טעינת ספריית Google Maps
        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&callback=initMap`;
        script.async = true;
        script.defer = true;
        document.head.appendChild(script);

        // ניקוי הסקריפט בזמן פירוק הקומפוננטה
        return () => {
            document.head.removeChild(script);
        };
    }, []);

    const changeView = () => {
        if (map) {
            const telAviv = { lat: 32.0853, lng: 34.7818 };
            map.setZoom(12);
            map.setCenter(telAviv);
        }
    };

    return (
        <div>
            <button className="button" onClick={changeView}>Change View</button>
            <div id="map"></div>
        </div>
    );
};

export default Map;
